insert into public.productos (nombre, categoria, precio, stock, imagen_url, descripcion) values
  ('Neo 1 antiséptico 130 ml', 'Neo 1 · Antisépticos', 7.59, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-004-004.jpg', 'Antiséptico avanzado de grado médico a base de Ácido Hipocloroso (HOCl) para piel, mucosas y boca. Multiespecie (perros, gatos, aves, reptiles), hipoalergénico, no irritante y no tóxico en caso de ingestión. Usos: heridas, quemaduras y úlceras; infecciones por hongos, bacterias y virus; mal aliento, sarro y gingivitis. Listo para usar: rociar sobre la piel o en la boca 2 veces al día. Conservar vertical, en lugar fresco y sin sol directo. Promoción: 3+2, 6+4 +3% de descuento, 9+6 +5% de descuento.'),
  ('Neo 1 antiséptico 1 litro', 'Neo 1 · Antisépticos', 22.00, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-004-004.jpg', 'Antiséptico avanzado de grado médico a base de Ácido Hipocloroso (HOCl) para piel, mucosas y boca. Multiespecie (perros, gatos, aves, reptiles), hipoalergénico, no irritante y no tóxico en caso de ingestión. Usos: heridas, quemaduras y úlceras; infecciones por hongos, bacterias y virus; mal aliento, sarro y gingivitis. Listo para usar: rociar sobre la piel o en la boca 2 veces al día. Conservar vertical, en lugar fresco y sin sol directo. Promoción: 3% de descuento adicional desde 6 unidades.'),
  ('ClorOne Vet desinfectante 2 litros', 'Neo 1 · Antisépticos', 6.90, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-005-005.jpg', 'Desinfectante de alto nivel con Ácido Hipocloroso (HOCl), seguro en presencia de mascotas y personas. Para quirófanos, instrumental, estética animal y el hogar (juguetes, camas, platos). Rociar, dejar actuar 1 a 5 minutos y dejar secar; no requiere enjuague. Apto para nebulización en frío.'),
  ('EnzyOne detergente enzimático 1 litro', 'Neo 1 · Antisépticos', 16.56, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-006-006.jpg', 'Detergente multienzimático tipo 5 para instrumental clínico, odontológico y veterinario. Degrada sangre, proteínas, tejidos y mucosas; pH neutro, biodegradable y de baja espuma. Uso: 8 ml por litro de agua, sumergir 5 minutos, cepillar y enjuagar. No mezclar con cloro ni otros detergentes.'),
  ('EnzyOne detergente enzimático 1 galón', 'Neo 1 · Antisépticos', 57.50, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-006-007.jpg', 'Detergente multienzimático tipo 5 para instrumental clínico, odontológico y veterinario. Degrada sangre, proteínas, tejidos y mucosas; pH neutro, biodegradable y de baja espuma. Uso: 8 ml por litro de agua, sumergir 5 minutos, cepillar y enjuagar. No mezclar con cloro ni otros detergentes.'),
  ('Simbyos SP perro / gato', 'Nutritoys · Alimento y suplementos', 9.94, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-008-008.jpg', 'Prebiótico simbiótico con Bacillus subtilis: regenera la microbiota intestinal, mejora la absorción de nutrientes y previene diarreas y alergias. Caja con 7 sobres de 5 g. Mezclar 1 sobre con agua o con el alimento; 1 tratamiento de 7 días al mes.'),
  ('Simbyos AID perro / gato', 'Nutritoys · Alimento y suplementos', 9.94, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-008-010.jpg', 'Probiótico + prebiótico + Yucca schidigera: reduce el mal olor de las heces y mejora la asimilación de nutrientes. Caja con 7 sobres de 5 g. Mezclar con el alimento; 1 tratamiento de 7 días al mes.'),
  ('DQ Patox protector hepático perro / gato', 'Nutritoys · Alimento y suplementos', 11.60, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-009-012.jpg', 'Protector hepático con silimarina: regenera y protege el hígado, mejora la digestión de dietas grasas. Caja con 7 sobres de 5 g. Preventivo: 1 sobre semanal. Curativo: 1 sobre diario por 7 días.'),
  ('Alimento húmedo para perro 100 g', 'Nutritoys · Alimento y suplementos', 2.37, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-010-016.jpg', 'Alimento completo de alta palatabilidad, rico en proteína, con prebióticos, vitaminas, minerales y Omega 3, 6 y 9. Carne de res, huevo y vegetales (arroz, arveja, zanahoria).'),
  ('Alimento húmedo para gato 100 g', 'Nutritoys · Alimento y suplementos', 2.65, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-009-013.jpg', 'Alimento completo y balanceado de hígado de pollo con prebióticos y Omega 3, 6 y 9. Mejora la hidratación y estimula el apetito.'),
  ('Galletas para perro 150 g mini surtido', 'Nutritoys · Alimento y suplementos', 2.96, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-010-014.jpg', 'Galletas horneadas de grado humano con prebióticos y probióticos: mejoran la digestión y refuerzan las defensas. Harina de trigo y maíz, salvado, miel, sabores naturales, vitaminas y minerales.'),
  ('Galletas para perro 250 g (surtido, avena, mango o zanahoria)', 'Nutritoys · Alimento y suplementos', 4.62, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-010-015.jpg', 'Galletas horneadas de grado humano con prebióticos y probióticos: mejoran la digestión y refuerzan las defensas. Harina de trigo y maíz, salvado, miel, sabores naturales, vitaminas y minerales.'),
  ('Michiko snack semanario (7 sachets)', 'Nutritoys · Alimento y suplementos', 8.57, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-011-018.jpg', 'Golosina húmeda y cremosa para gatos, sin colorantes ni conservantes, con vitamina E. Un sabor para cada día: salmón, pollo, atún, pescados de mar con atún, pollo y queso, atún con camarón y pollo con pato. 7 sachets de 14 g.'),
  ('Michiko snack 4 sachets', 'Nutritoys · Alimento y suplementos', 5.09, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-011-019.jpg', 'Golosina húmeda y cremosa para gatos, sin colorantes ni conservantes, con vitamina E. Sabores: pollo, atún, salmón o atún y salmón. 4 sachets de 14 g.'),
  ('Michiko filete de pollo / atún', 'Nutritoys · Alimento y suplementos', 3.20, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-012-024.jpg', 'Snack natural de textura húmeda y tierna, 100% proteína, rico en Omega 3 y 6, sin conservantes ni colorantes. 25 g. Apto para perros según criterio del veterinario.'),
  ('Michiko filete de salmón', 'Nutritoys · Alimento y suplementos', 3.43, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-012-025.jpg', 'Snack natural de textura húmeda y tierna, 100% proteína, rico en Omega 3 y 6, sin conservantes ni colorantes. 25 g. Apto para perros según criterio del veterinario.'),
