  ('Vacuna Vibix C5', 'Vacunas', 4.32, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-015-029.jpg', 'Vacuna contra moquillo, adenovirus tipo 2, parvovirus, parainfluenza y leptospira (4 serovares). Precio por unidad; caja de 10: $43.20. Promoción: 1 jeringuilla gratis por cada vacuna.'),
  ('Vacuna Vibix C6R', 'Vacunas', 6.48, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-016-030.jpg', 'Vacuna contra moquillo, hepatitis, parvovirus, parainfluenza, leptospira (4 serovares) y rabia. Precio por unidad; caja de 10: $64.80. Promoción: 1 jeringuilla gratis por cada vacuna.'),
  ('Vacuna Vibix Rabia', 'Vacunas', 2.60, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-016-031.jpg', 'Vacuna inactivada contra la rabia para perros y gatos desde las 12 semanas. Precio por unidad; caja de 10: $26.00. Promoción: 1 jeringuilla gratis por cada vacuna.'),
