  ('Vacuna Felocell FeLV (gatos)', 'Vacunas', 9.98, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-018-035.jpg', 'Vacuna preventiva contra la leucemia viral felina. Precio por unidad; caja de 25: $249.50.'),
