  ('Sutura polidioxanona', 'Suturas', 2.08, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-019-037.jpg', 'Sutura absorbible. Precio por unidad, cualquier calibre; caja de 12: $24.96.'),
