  ('Test Parvovirus Ag / Coronavirus Ag', 'Tests Bioguard', 7.40, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-021-039.jpg', 'Test rápido Bioguard de parvovirus y coronavirus canino. Precio por unidad; caja de 10: $64.00.'),
