  ('Test FeLV Ag / FIV Ab (leucemia y sida felino)', 'Tests Bioguard', 9.95, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-023-044.jpg', 'Test rápido Bioguard para gatos. Precio por unidad; caja de 10: $89.50.'),
  ('Kit tipificación sanguínea felina', 'Tests Bioguard', 20.80, 10, 'https://nsdngcbsjaxnbgociksi.supabase.co/storage/v1/object/public/productos/i-024-045.jpg', 'Kit Bioguard para tipificar sangre de gatos. Precio por unidad; caja de 5: $99.00.'),
